106	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queues */
107	static void vTaskButton(void *pvParameters)
108	{
109	    (void)pvParameters;
110	    uint8_t prev_state = 0;
111	
112	    for (;;) {
113	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
114	        if (state && !prev_state) {
115	            uint32_t msg = 1;
116	            if (xButtonQueue != NULL) {
117	                xQueueSend(xButtonQueue, &msg, 0);
118	            }
119	            if (xUIQueue != NULL) {
120	                xQueueSend(xUIQueue, &msg, 0);

121	            }
122	        }
123	        prev_state = state;
124	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
125	    }
126	}
127	
128	/* Task 3: Chờ tín hiệu từ Queue để đổi trạng thái LED3 (PD5) */
129	static void vTaskLED3(void *pvParameters)
130	{
131	    (void)pvParameters;
132	    uint32_t rx_msg = 0;
133	    uint8_t led_state = 0;
134	
135	    for (;;) {
136	        if (xQueueReceive(xButtonQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
137	            led_state = !led_state;
138	            if (led_state) {
139	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
140	            } else {
141	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
142	            }
143	        }
144	    }
145	}
146	
147	/* Task 4: Giám sát hệ thống qua LED4 (PK3) - nhịp tim định kỳ */
148	static void vTaskMonitor(void *pvParameters)
149	{
150	    (void)pvParameters;
151	    for (;;) {
152	        GPIOK->BSRR = (1UL << (LED4_PIN + 16)); /* Bật LED4 */
153	        vTaskDelay(pdMS_TO_TICKS(100));
154	        GPIOK->BSRR = (1UL << LED4_PIN);        /* Tắt LED4 */
155	        vTaskDelay(pdMS_TO_TICKS(1900));
156	    }
157	}
158	
159	/* Task 5: Quản lý hiển thị LCD DSI OTM8009A và cập nhật giao diện */
160	static void vTaskLCD(void *pvParameters)
161	{
162	    (void)pvParameters;
163	    uint32_t rx_msg = 0;
164	
165	    /* Khởi tạo SDRAM và màn hình LCD DSI */
166	    UI_Init();
167	
168	    for (;;) {
169	        if (xQueueReceive(xUIQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
170	            UI_ToggleScreen();
171	        }
172	    }
173	}
