175	int main(void)
176	{
177	    prvSetupHardware();
178	
179	    /* Tạo queue chứa sự kiện nút bấm */
180	    xButtonQueue = xQueueCreate(4, sizeof(uint32_t));
181	    xUIQueue     = xQueueCreate(4, sizeof(uint32_t));
182	
183	    /* Tạo các tác vụ ứng dụng LED, nút bấm và hiển thị LCD */
184	    xTaskCreate(vTaskLED1,    "LED1_1000ms", configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
185	    xTaskCreate(vTaskLED2,    "LED2_400ms",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
186	    xTaskCreate(vTaskButton,  "BtnPoll",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 2, NULL);
187	    xTaskCreate(vTaskLED3,    "LED3_Queue",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
188	    xTaskCreate(vTaskMonitor, "Monitor",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
189	    xTaskCreate(vTaskLCD,      "LCD_Task",    configMINIMAL_STACK_SIZE * 4,   NULL, tskIDLE_PRIORITY + 1, NULL);
190	
191	    /* Bắt đầu FreeRTOS scheduler */
192	    vTaskStartScheduler();
193	
194	    /* Không bao giờ tới đây */
195	    for (;;);
196	    return 0;
197	}

